21	        BigDecimal discount,
22	        BigDecimal total) {
23	
24	    public ReservationReceipt(Reservation reservation, Room room) {
25	        this(
26	                "Comprovante de reserva",
27	                reservation.id(),
28	                reservation.guest().name(),
29	                reservation.guest().cpf(),
30	                room.number(),
31	                room.type(),
32	                reservation.checkIn(),
33	                reservation.checkOut(),
34	                reservation.price().nights(),
35	                reservation.price().subtotal(),
36	                reservation.price().discount(),
37	                reservation.price().total());
38	    }
39	
40	    public String text() {
41	        StringBuilder text = new StringBuilder();
42	        text.append(title).append(" nº ").append(reservationId).append('\n');
43	        text.append("Hóspede: ").append(guestName).append(" (CPF ").append(guestCpf).append(")\n");
44	        text.append("Quarto: ").append(roomNumber).append(" (").append(roomType).append(")\n");
45	        text.append("Entrada: ").append(TextFormat.date(checkIn))
46	                .append(" | Saída: ").append(TextFormat.date(checkOut))
47	                .append(" | ").append(nights).append(nights == 1 ? " diária" : " diárias").append('\n');
48	        text.append("Diárias: ").append(TextFormat.money(subtotal)).append('\n');
49	        if (discount.signum() > 0) {
50	            text.append("Desconto: ").append(TextFormat.money(discount)).append('\n');
51	        }
52	        text.append("Total: ").append(TextFormat.money(total)).append('\n');
53	        return text.toString();
54	    }
55	}
